  background: #050505;
  color: var(--threeui-page-ink);
  font-family: Inter, "Helvetica Neue", Helvetica, Arial, sans-serif;
}
.threeui-page-button-stage::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
}
.threeui-page-button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
