  border: 1px solid rgba(255, 255, 255, .27);
  background: linear-gradient(180deg, rgba(255, 255, 255, .07), rgba(0, 0, 0, .36));
  box-shadow: 0 15px 36px rgba(0, 0, 0, .48), inset 0 1px rgba(255, 255, 255, .08);
  color: rgba(255, 255, 255, .82);
